import numpy as np

def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
    return X, y

def close(got, exp: List[float], rtol: float = 1e-9, atol: float = 1e-11) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        if abs(g[i] - exp[i]) > atol + rtol * abs(exp[i]):
            print("mismatch at", i, g[i], exp[i])
            return False
    return True

def flat(cv, X, y, groups):
    tr = List[float](); te = List[float]()
    for a, b in cv.split(X, y, groups):
        for v in a: tr.append(float(v))
        tr.append(-1.0)
        for v in b: te.append(float(v))
        te.append(-1.0)
    return tr, te

def chk(name: str, cv, X, y, groups, etr: List[float], ete: List[float]):
    tr, te = flat(cv, X, y, groups)
    if not (close(tr, etr) and close(te, ete)):
        print("FAIL", name)
        assert False

def pvf(ps, key: str) -> List[float]:
    return [float(p[key]) for p in ps]

