from sklearn.model_selection import (GroupKFold, StratifiedGroupKFold, RepeatedKFold,
    RepeatedStratifiedKFold, ShuffleSplit, StratifiedShuffleSplit, GroupShuffleSplit,
    LeaveOneOut, LeavePOut, LeaveOneGroupOut, LeavePGroupsOut, PredefinedSplit, TimeSeriesSplit,
    train_test_split)

@test
def test_splitters():
    X, y = data(24, 3, 3)
    g = np.array([i % 6 for i in range(24)])
    chk("gkf", GroupKFold(3), X, y, g, gkf_tr, gkf_te)
    chk("gkfs", GroupKFold(3, shuffle=True, random_state=1), X, y, g, gkfs_tr, gkfs_te)
    chk("sgkf", StratifiedGroupKFold(3), X, y, np.arange(24) // 3, sgkf_tr, sgkf_te)
    chk("rkf", RepeatedKFold(n_splits=3, n_repeats=2, random_state=0), X, None, None, rkf_tr, rkf_te)
    chk("rskf", RepeatedStratifiedKFold(n_splits=2, n_repeats=2, random_state=3), X, y, None, rskf_tr, rskf_te)
    chk("ss", ShuffleSplit(3, test_size=0.25, random_state=0), X, None, None, ss_tr, ss_te)
    chk("ss2", ShuffleSplit(2, test_size=5, train_size=10, random_state=4), X, None, None, ss2_tr, ss2_te)
    chk("sss", StratifiedShuffleSplit(3, test_size=0.25, random_state=0), X, y, None, sss_tr, sss_te)
    chk("gss", GroupShuffleSplit(2, test_size=0.34, random_state=0), X, y, g, gss_tr, gss_te)
    X4 = X[:4]
    chk("loo", LeaveOneOut(), X4, None, None, loo_tr, loo_te)
    chk("lpo", LeavePOut(2), X4, None, None, lpo_tr, lpo_te)
    chk("logo", LeaveOneGroupOut(), X, y, g, logo_tr, logo_te)
    chk("lpgo", LeavePGroupsOut(2), X[:12], None, g[:12] % 4, lpgo_tr, lpgo_te)
    chk("ps", PredefinedSplit([0, 1, -1, 0, 1, 2, 2, -1]), X[:8], None, None, ps_tr, ps_te)
    chk("tss", TimeSeriesSplit(3), X, None, None, tss_tr, tss_te)
    chk("tss2", TimeSeriesSplit(3, max_train_size=6, test_size=3, gap=1), X, None, None, tss2_tr, tss2_te)
    a, b, c, d = train_test_split(X, y, test_size=0.25, random_state=0, stratify=y)
    assert close(a, tts_a) and close(d, tts_d)
test_splitters()
